using CircuitRF.Core.Tests.Composed;
using CircuitRF.Design.Modeling;
using CircuitRF.Design.Schematic;
using CircuitRF.Engine.Modeling;
using Xunit;
using Xunit.Abstractions;

namespace CircuitRF.Ui.Tests.ModelComposer;

/// <summary>
/// brief-modelcomposer-4 R-mc4-3: S generated by circuitRF from a known linear core inside a network written by hand
/// de-embeds, through the STOCK schematic of that network solved by the linear engine as a 4-port, to the core's own
/// Y at every frequency. Also holds R-mc4-2's pin contract and R-mc4-6's cache.
/// </summary>
public sealed class DeembedThroughNetworkTests(ITestOutputHelper output)
{
    private static readonly double[] Freqs = [0.5e9, 2e9, 8e9, 20e9, 40e9];

    [Theory]
    [InlineData("gan-two-shell")]
    [InlineData("classic-shell")]
    public void KnownCore_InsideTheNetwork_DeembedsToItsY(string stock)
    {
        var data = stock == "gan-two-shell"
            ? SyntheticFetData.CoreS(ComposedTestModels.GanNetwork, "gan", Freqs)
            : SyntheticFetData.CoreS(SyntheticFetData.ClassicNetwork, "classic", Freqs);
        var blocks = SyntheticFetData.Stock(stock).Blocks(Freqs);

        for (int k = 0; k < Freqs.Length; k++)
        {
            var yExt = NetworkAlgebra.SToY(new C2(data.SAt(0, k, 0, 0), data.SAt(0, k, 0, 1), data.SAt(0, k, 1, 0), data.SAt(0, k, 1, 1)), 50);
            var r = NetworkAlgebra.Deembed(blocks[k].Aa, blocks[k].Ab, blocks[k].Ba, blocks[k].Bb, yExt);
            var truth = SyntheticFetData.CoreY(Freqs[k]);
            double err = (r.YInt - truth).MaxAbs / truth.MaxAbs;
            output.WriteLine($"{stock} {Freqs[k] / 1e9} GHz: rel error {err:E2}, condition {r.Condition:E2}");
            Assert.True(err < 1e-9, $"{Freqs[k] / 1e9} GHz: relative error {err:E3}");
            Assert.False(r.Flagged);
        }
        // Not vacuous: the network moves the admittance well away from the core's.
        var raw = data.SAt(0, 2, 1, 0);
        var bare = SyntheticFetData.CoreS(null, null, Freqs).SAt(0, 2, 1, 0);
        Assert.True((raw - bare).Magnitude > 1e-3);
    }

    [Fact]
    public void WrongPinCount_IsRefused_ListingThePinsFound()
    {
        string dir = Directory.CreateTempSubdirectory("crf-mc4-pins-").FullName;
        string path = StockNetworks.CopyInto(dir, "series-only");
        // Renumber pin 5 as a second pin 4.
        var (model, _, cell) = SchematicPersistence.LoadFromFile(path);
        model.Components.Single(c => c.Symbol == SymbolKind.Pin && c.Parameters.Any(p => p.Name == "Num" && p.Expression == "5"))
             .Parameters.Single(p => p.Name == "Num").Expression = "4";
        SchematicPersistence.SaveToFile(path, model, cell);

        var ex = Assert.Throws<ModelingException>(() => SixPinNetwork.Load(path));
        Assert.Equal("series-only.csch: an extrinsic network has exactly 6 pins numbered 1 to 6; found 1, 2, 3, 4, 4, 6.", ex.Message);
    }

    [Fact]
    public void UnchangedNetwork_ReopensFromTheCache()
    {
        string dir = Directory.CreateTempSubdirectory("crf-mc4-cache-").FullName;
        string cmc = Path.Combine(dir, "fet.cmc");
        var doc = StockNetworks.Choose(new CmcDocument { Kind = CmcKind.Active, DataSets = [SyntheticFetData.Set("bias", ReferencePlane.Device)] },
                                       cmc, "gan-two-shell");
        var data = new Dictionary<string, NormalisedData> { ["bias"] = SyntheticFetData.CoreS(ComposedTestModels.GanNetwork, "gan", Freqs) };

        var first = new IntrinsicExtraction(cmc);
        var a = first.Run(doc, data);
        var second = new IntrinsicExtraction(cmc);
        var b = second.Run(doc, data);
        var third = new IntrinsicExtraction(cmc);
        third.Run(doc, data, new Dictionary<string, double> { ["Lg"] = 45e-12 });

        Assert.Equal((1L, 0L, 1L), (first.Computations, second.Computations, third.Computations));
        Assert.Equal(a.Sets["bias"]["Cgs"].RealValues, b.Sets["bias"]["Cgs"].RealValues);
    }
}
